        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            r,c=s[0]+dr,s[1]+dc
            if 0<=r<H and 0<=c<W and (r,c) not in walls:
                dist[(r,c)]=(s,(dr,dc)); q.append((r,c))
