        if cur in tgts: end=cur; break
        r,c=cur
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and (nr,nc) not in walls and (nr,nc) not in dist:
                dist[(nr,nc)]=(cur,(dr,dc)); q.append((nr,nc))
